const handleSOS = async () => {
  if (
    Platform.OS === "web" &&
    typeof window !== "undefined" &&
    "Notification" in window
  ) {
    Notification.requestPermission().then((permission) => {
      if (permission === "granted") {
        new Notification("SOS Ativado", {
          body: "O pedido de socorro foi enviado.",
        });
      } else {
        Alert.alert("SOS Ativado", "O pedido de socorro foi enviado.");
      }
    });
  } else {
    try {
      await sendLocalSOSNotification();
    } catch {
      Alert.alert(
        "Permissao Necessaria",
        "Ative as notificacoes do dispositivo para receber alertas SOS.",
      );
    }
  }
};

interface SOSButtonProps {
  compact?: boolean;
}

export const SOSButton = ({ compact = false }: SOSButtonProps) => {
  return (
    <TouchableOpacity
      onPress={handleSOS}
      activeOpacity={0.85}
      accessibilityRole="button"
      accessibilityLabel="Ativar SOS"
      accessibilityHint="Envia um pedido de socorro."
    >
      <View
        className={`${compact ? "w-44 gap-2" : "w-64 gap-4"} h-12 p-2 bg-red-600 rounded-[20px] flex-row justify-center items-center`}
        style={
          {
            boxShadow: "inset 0px 0px 50px -25px rgba(255, 127, 129, 1.00)",
          } as any
        }
      >
        {/* Left antena — mirrored so arcs point outward left */}
        <View style={{ transform: [{ scaleX: -1 }] }}>
          <AntenaSvg />
        </View>

        {/* SOS text */}
        <SOSSvg />

        {/* Right antena — arcs point outward right */}
        <AntenaSvg />
      </View>
    </TouchableOpacity>
  );
};

export default SOSButton;
